import type { ComponentProps, ReactNode } from "react";

import { Badge } from "../../badge/badge";
import { cn } from "../../lib/cn";

export function Pricing({ className, ...props }: ComponentProps<"section">) {
  return (
    <section
      data-slot="pricing"
      className={cn("mx-auto w-full max-w-5xl px-4 py-16 sm:py-24", className)}
      {...props}
    />
  );
}

export function PricingHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="pricing-header"
      className={cn(
        "mx-auto mb-8 flex max-w-2xl flex-col items-center gap-3 text-center",
        className,
      )}
      {...props}
    />
  );
}

export function PricingTitle({ className, ...props }: ComponentProps<"h2">) {
  return (
    // The heading is the caller's own text, passed in as children.
    // oxlint-disable-next-line jsx-a11y/heading-has-content
    <h2
      data-slot="pricing-title"
      className={cn("text-3xl font-semibold tracking-tight text-balance sm:text-4xl", className)}
      {...props}
    />
  );
}

export function PricingDescription({ className, ...props }: ComponentProps<"p">) {
  return (
    <p
      data-slot="pricing-description"
      className={cn("text-base text-pretty text-muted-foreground", className)}
      {...props}
    />
  );
}

export interface PricingToggleProps {
  annual: boolean;
  onAnnualChange: (annual: boolean) => void;
  monthlyLabel?: string;
  annualLabel?: string;
  /** Small note on the annual option, e.g. "Save 20%". */
  annualNote?: string;
}

/**
 * Controlled on purpose: the prices are the caller's to compute, so the toggle
 * never has to know what a tier costs.
 */
export function PricingToggle({
  annual,
  onAnnualChange,
  monthlyLabel = "Monthly",
  annualLabel = "Annual",
  annualNote,
}: PricingToggleProps) {
  return (
    <div
      role="group"
      aria-label="Billing period"
      className="inline-flex items-center gap-1 rounded-full border border-border bg-secondary/60 p-1"
    >
      <button
        type="button"
        aria-pressed={!annual}
        onClick={() => onAnnualChange(false)}
        className={cn(
          "rounded-full px-3.5 py-1.5 text-sm font-medium transition-colors",
          !annual
            ? "bg-background text-foreground shadow-xs"
            : "text-muted-foreground hover:text-foreground",
        )}
      >
        {monthlyLabel}
      </button>
      <button
        type="button"
        aria-pressed={annual}
        onClick={() => onAnnualChange(true)}
        className={cn(
          "flex items-center gap-2 rounded-full px-3.5 py-1.5 text-sm font-medium transition-colors",
          annual
            ? "bg-background text-foreground shadow-xs"
            : "text-muted-foreground hover:text-foreground",
        )}
      >
        {annualLabel}
        {annualNote ? <span className="text-xs text-brand">{annualNote}</span> : null}
      </button>
    </div>
  );
}

export function PricingGrid({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="pricing-grid"
      className={cn("mt-10 grid gap-4 md:grid-cols-3", className)}
      {...props}
    />
  );
}

export interface PricingTierProps extends Omit<ComponentProps<"div">, "children"> {
  name: string;
  /** What the period costs, e.g. "$24". */
  price: string;
  /** What that price is measured in, e.g. "per seat, per month". */
  period?: string;
  description?: ReactNode;
  features: string[];
  /** A stronger border and a label. Deliberately not a coloured card. */
  featured?: boolean;
  /** The call to action, usually a `Button`. */
  children?: ReactNode;
}

function Check({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 16 16" aria-hidden="true" className={className}>
      <path
        d="m3.5 8.5 3 3 6-6.5"
        fill="none"
        stroke="currentColor"
        strokeLinecap="round"
        strokeWidth="1.75"
      />
    </svg>
  );
}

export function PricingTier({
  name,
  price,
  period,
  description,
  features,
  featured = false,
  className,
  children,
  ...props
}: PricingTierProps) {
  return (
    <div
      data-slot="pricing-tier"
      className={cn(
        "flex flex-col gap-5 rounded-xl border bg-card p-6",
        featured ? "border-foreground/20 shadow-md" : "border-border shadow-xs",
        className,
      )}
      {...props}
    >
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-sm font-medium">{name}</h3>
        {featured ? <Badge variant="brand">Most popular</Badge> : null}
      </div>

      {description ? <p className="text-sm text-muted-foreground">{description}</p> : null}

      <p className="flex items-baseline gap-2">
        <span className="text-3xl font-semibold tracking-tight">{price}</span>
        {period ? <span className="text-sm text-muted-foreground">{period}</span> : null}
      </p>

      <ul className="grid gap-2.5 border-t border-border pt-5 text-sm">
        {features.map((feature) => (
          <li key={feature} className="flex items-start gap-2.5">
            <Check className="mt-0.5 size-4 shrink-0 text-brand" />
            <span className="text-muted-foreground">{feature}</span>
          </li>
        ))}
      </ul>

      <div className="mt-auto">{children}</div>
    </div>
  );
}

import type { ComponentProps } from "react";

import { cn } from "../lib/cn";

export type BadgeVariant = "neutral" | "brand" | "success" | "warning" | "destructive";
export type BadgeSize = "sm" | "md";

export interface BadgeProps extends ComponentProps<"span"> {
  variant?: BadgeVariant;
  size?: BadgeSize;
}

// Chromatic badges are a tint with ink text rather than a coloured label: at
// eleven pixels a saturated chip reads as decoration, not information. Put a
// dot or an icon inside the badge when the state has to be obvious at a glance.
const variants = {
  neutral: "border-transparent bg-secondary text-secondary-foreground",
  brand: "border-transparent bg-brand-subtle text-brand-strong",
  success: "border-success/25 bg-success/10 text-foreground",
  warning: "border-warning/25 bg-warning/10 text-foreground",
  destructive: "border-destructive/25 bg-destructive/10 text-foreground",
} satisfies Record<BadgeVariant, string>;

const sizes = {
  sm: "h-5 gap-1 px-1.5 text-[0.6875rem] leading-none",
  md: "h-6 gap-1.5 px-2 text-xs leading-none",
} satisfies Record<BadgeSize, string>;

export function Badge({ className, variant = "neutral", size = "md", ...props }: BadgeProps) {
  return (
    <span
      data-slot="badge"
      className={cn(
        "inline-flex items-center rounded-full border font-medium whitespace-nowrap transition-colors [&_svg]:pointer-events-none [&_svg]:size-3 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      {...props}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

/**
 * Forme's type styles, so tailwind-merge stops treating them as colours.
 *
 * The bug this prevents, which was live in this file for a while and is
 * invisible in the source: `tailwind-merge` has no view of a Tailwind theme. Any
 * `text-*` utility it does not recognise as one of Tailwind's built-in font sizes
 * is assumed to be a text **colour**. So on a button whose classes were
 * `p-2 text-body bg-button-primary text-white`, it saw two text-colours, applied
 * last-write-wins, and silently dropped `text-body`. The class was in the source,
 * the utility was in the stylesheet, the DOM had it on the element — and the
 * button rendered at 16px instead of 14px. Nothing errored.
 *
 * Registering them under `font-size` is the fix, and every name added to
 * typography.css has to be added here too. That duplication is the price: the
 * alternative is a type utility that a caller can delete by accident.
 *
 * If you rename or add a type style in foundation.css, mirror it in this list.
 */
const TEXT_FAMILIES = [
  "body",
  "body-2",
  "caption-1",
  "caption-2",
  "title-1",
  "title-2",
  "title-3",
  "headline",
] as const;

const TEXT_WEIGHTS = ["regular", "medium", "semibold", "bold"] as const;

const TEXT_STYLES = TEXT_FAMILIES.flatMap((family) =>
  TEXT_WEIGHTS.map((weight) => `${family}-${weight}`),
);

const merge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [{ text: TEXT_STYLES }],
    },
  },
});

/**
 * Merges class names, letting a caller's `className` win over a component's
 * defaults. Without the merge step a `px-4` from the component and a `px-6` from
 * the caller would both reach the browser and the winner would be whichever came
 * last in the stylesheet rather than whichever the caller meant.
 */
export function cn(...inputs: ClassValue[]): string {
  return merge(clsx(inputs));
}
